361	//  §6.1 L2 persistence for per-step optimizer state (Hopper sm_90+).
362	//
363	//  Optimizer state (m, v, EMA, mu, …) is read+written every step and is the
364	//  hottest reuse in the whole pipeline. We hint the L2 cache to keep it
365	//  resident across the step via the SAFE RUNTIME API
366	//  (cudaStreamSetAttribute + cudaAccessPolicyWindow) — NOT hand-written
367	//  `createpolicy` PTX, which trips the known CUDA-13.1 ptxas lowering bug.
368	//
369	//  Use as an RAII scope around the kernel launch(es) in a host launcher:
370	//      { L2PersistScope l2(stream, exp_avg.data_ptr(), exp_avg.nbytes(),
371	//                          exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
372	//        kernel<<<...,stream>>>(...); }
373	//  On construction it carves a persisting window over the (contiguous-ish)
374	//  span covering the given buffers; on destruction it resets the policy and
375	//  releases the carve-out so the next op sees a clean L2.
376	//
377	//  Gated by ENABLE_L2_PERSIST and a runtime check: if the requested span is
378	//  larger than the device's reservable persisting-L2 (cudaDevAttrMax-
379	//  PersistingL2CacheSize, ~50 MB on H100) — or the device predates Hopper —
380	//  the scope is a no-op (and logs nothing on the hot path).
381	// =========================================================================
382	
383	#ifndef ENABLE_L2_PERSIST
384	#define ENABLE_L2_PERSIST 1
385	#endif
